136	  tag: string | Function
137	  props: Props
138	  key?: string
139	  children: Child[]
140	  isEscaped: true = true as const
141	  localContexts?: LocalContexts
142	  constructor(tag: string | Function, props: Props, children: Child[]) {
143	    if (typeof tag !== 'function' && !isValidTagName(tag)) {
144	      throw new Error(`Invalid JSX tag name: ${tag}`)
145	    }
146	    this.tag = tag
147	    this.props = props
148	    this.children = children
149	  }
