151	  get type(): string | Function {
152	    return this.tag as string
153	  }
154	
155	  // Added for compatibility with libraries that rely on React's internal structure
156	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
157	  get ref(): any {
158	    return this.props.ref || null
159	  }
