161	  toString(): string | Promise<string> {
162	    const buffer: StringBufferWithCallbacks = [''] as StringBufferWithCallbacks
163	    this.localContexts?.forEach(([context, value]) => {
164	      context.values.push(value)
165	    })
166	    try {
167	      this.toStringToBuffer(buffer)
168	    } finally {
169	      this.localContexts?.forEach(([context]) => {
170	        context.values.pop()
171	      })
172	    }
173	    return buffer.length === 1
174	      ? 'callbacks' in buffer
175	        ? resolveCallbackSync(raw(buffer[0], buffer.callbacks)).toString()
176	        : buffer[0]
177	      : stringBufferToString(buffer, buffer.callbacks)
178	  }
