1	import { raw } from '../../helper/html'
2	import type { HtmlEscapedCallback, HtmlEscapedString } from '../../utils/html'
3	import { JSXNode, getNameSpaceContext } from '../base'
4	import type { Child, Props } from '../base'
5	import { toArray } from '../children'
6	import { PERMALINK } from '../constants'
7	import { useContext } from '../context'
8	import type { IntrinsicElements } from '../intrinsic-elements'
9	import type { FC, PropsWithChildren } from '../types'
10	import {
11	  dataPrecedenceAttr,
12	  deDupeKeyMap,
13	  isStylesheetLinkWithPrecedence,
14	  shouldDeDupeByKey,
15	} from './common'
16	
17	const metaTagMap: WeakMap<
18	  object,
19	  Record<string, [string, Props, string | undefined][]>
20	> = new WeakMap()
21	const insertIntoHead: (
22	  tagName: string,
23	  tag: string,
24	  props: Props,
25	  precedence: string | undefined
26	) => HtmlEscapedCallback =
27	  (tagName, tag, props, precedence) =>
28	  ({ buffer, context }): undefined => {
29	    if (!buffer) {
30	      return
31	    }
32	    const map = metaTagMap.get(context) || {}
33	    metaTagMap.set(context, map)
34	    const tags = (map[tagName] ||= [])
35	
36	    let duped = false
37	    const deDupeKeys = deDupeKeyMap[tagName]
38	    const deDupeByKey = shouldDeDupeByKey(tagName, precedence !== undefined)
39	    if (deDupeByKey) {
40	      LOOP: for (const [, tagProps] of tags) {
41	        if (
42	          tagName === 'link' &&
43	          !(tagProps.rel === 'stylesheet' && tagProps[dataPrecedenceAttr] !== undefined)
44	        ) {
45	          continue
46	        }
47	        for (const key of deDupeKeys) {
48	          if ((tagProps?.[key] ?? null) === props?.[key]) {
49	            duped = true
50	            break LOOP
51	          }
52	        }
53	      }
54	    }
55	
56	    if (duped) {
57	      buffer[0] = buffer[0].replaceAll(tag, '')
58	    } else if (deDupeByKey || tagName === 'link') {
59	      tags.push([tag, props, precedence])
60	    } else {
61	      tags.unshift([tag, props, precedence])
62	    }
63	
64	    if (buffer[0].indexOf('</head>') !== -1) {
65	      let insertTags
66	      if (tagName === 'link' || precedence !== undefined) {
67	        const precedences: string[] = []
68	        insertTags = tags
69	          .map(([tag, , tagPrecedence], index) => {
70	            if (tagPrecedence === undefined) {
71	              return [tag, Number.MAX_SAFE_INTEGER, index] as [string, number, number]
72	            }
73	            let order = precedences.indexOf(tagPrecedence as string)
74	            if (order === -1) {
75	              precedences.push(tagPrecedence as string)
76	              order = precedences.length - 1
77	            }
78	            return [tag, order, index] as [string, number, number]
79	          })
80	          .sort((a, b) => a[1] - b[1] || a[2] - b[2])
81	          .map(([tag]) => tag)
82	      } else {
83	        insertTags = tags.map(([tag]) => tag)
84	      }
85	
86	      insertTags.forEach((tag) => {
87	        buffer[0] = buffer[0].replaceAll(tag, '')
88	      })
89	      buffer[0] = buffer[0].replace(/(?=<\/head>)/, insertTags.join(''))
90	    }
91	  }
92	
93	const returnWithoutSpecialBehavior = (tag: string, children: Child, props: Props) =>
94	  raw(new JSXNode(tag, props, toArray(children ?? [])).toString())
95	
96	const documentMetadataTag = (tag: string, children: Child, props: Props, sort: boolean) => {
97	  if ('itemProp' in props) {
98	    return returnWithoutSpecialBehavior(tag, children, props)
99	  }
100	
101	  let { precedence, blocking, ...restProps } = props
102	  precedence = sort ? (precedence ?? '') : undefined
103	  if (sort) {
104	    restProps[dataPrecedenceAttr] = precedence
105	  }
106	
107	  const string = new JSXNode(tag, restProps, toArray(children || [])).toString()
108	
109	  if (string instanceof Promise) {
110	    return string.then((resString) =>
111	      raw(string, [
112	        ...((resString as HtmlEscapedString).callbacks || []),
113	        insertIntoHead(tag, resString, restProps, precedence),
114	      ])
115	    )
116	  } else {
117	    return raw(string, [insertIntoHead(tag, string, restProps, precedence)])
118	  }
119	}
120	
121	export const title: FC<PropsWithChildren> = ({ children, ...props }) => {
122	  const nameSpaceContext = getNameSpaceContext()
123	  if (nameSpaceContext) {
124	    const context = useContext(nameSpaceContext)
125	    if (context === 'svg' || context === 'head') {
126	      return new JSXNode(
127	        'title',
128	        props,
129	        toArray(children ?? []) as Child[]
130	      ) as unknown as HtmlEscapedString
131	    }
132	  }
133	
134	  return documentMetadataTag('title', children, props, false)
135	}
136	export const script: FC<PropsWithChildren<IntrinsicElements['script']>> = ({
137	  children,
138	  ...props
139	}) => {
140	  const nameSpaceContext = getNameSpaceContext()
141	  if (
142	    ['src', 'async'].some((k) => !props[k]) ||
143	    (nameSpaceContext && useContext(nameSpaceContext) === 'head')
144	  ) {
145	    return returnWithoutSpecialBehavior('script', children, props)
146	  }
147	
148	  return documentMetadataTag('script', children, props, false)
149	}
150	
151	export const style: FC<PropsWithChildren<IntrinsicElements['style']>> = ({
152	  children,
153	  ...props
154	}) => {
155	  if (!['href', 'precedence'].every((k) => k in props)) {
156	    return returnWithoutSpecialBehavior('style', children, props)
157	  }
158	  props['data-href'] = props.href
159	  delete props.href
160	  return documentMetadataTag('style', children, props, true)
161	}
162	export const link: FC<PropsWithChildren<IntrinsicElements['link']>> = ({ children, ...props }) => {
163	  if (
164	    ['onLoad', 'onError'].some((k) => k in props) ||
165	    (props.rel === 'stylesheet' && (!('precedence' in props) || 'disabled' in props))
166	  ) {
167	    return returnWithoutSpecialBehavior('link', children, props)
168	  }
169	  return documentMetadataTag('link', children, props, isStylesheetLinkWithPrecedence(props))
170	}
171	export const meta: FC<PropsWithChildren> = ({ children, ...props }) => {
172	  const nameSpaceContext = getNameSpaceContext()
173	  if (nameSpaceContext && useContext(nameSpaceContext) === 'head') {
174	    return returnWithoutSpecialBehavior('meta', children, props)
175	  }
176	  return documentMetadataTag('meta', children, props, false)
177	}
178	
179	const newJSXNode = (tag: string, { children, ...props }: PropsWithChildren<unknown>) =>
180	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
181	  new JSXNode(tag, props, toArray(children ?? []) as Child[]) as any
182	export const form: FC<
183	  PropsWithChildren<{
184	    action?: Function | string
185	    method?: 'get' | 'post'
186	  }>
187	> = (props) => {
188	  if (typeof props.action === 'function') {
189	    props.action = PERMALINK in props.action ? (props.action[PERMALINK] as string) : undefined
190	  }
191	  return newJSXNode('form', props)
192	}
193	
194	const formActionableElement = (
195	  tag: string,
196	  props: PropsWithChildren<{
197	    formAction?: Function | string
198	  }>
199	) => {
200	  if (typeof props.formAction === 'function') {
201	    props.formAction =
202	      PERMALINK in props.formAction ? (props.formAction[PERMALINK] as string) : undefined
203	  }
204	  return newJSXNode(tag, props)
205	}
206	
207	export const input: (props: PropsWithChildren) => unknown = (props) =>
208	  formActionableElement('input', props)
209	export const button: (props: PropsWithChildren) => unknown = (props) =>
210	  formActionableElement('button', props)
